import {qualityWorkspace,qualityCommand,downloadEvidence,exportQuality} from '@/services/quality'
const catalogManager=ref<'auditor'|'area'|null>(null)
const route=useRoute(),router=useRouter(),auth=useAuthStore(),data=ref<any>(null),error=ref(''),busy=ref(false),search=ref(String(route.query.q||'')),filter=ref(String(route.query.filter||'')),year=ref(''),area=ref(''),responsible=ref(''),origin=ref(''),auditor=ref(''),auditFilter=ref('')
const dialog=ref<{title:string;operation:string;id?:string;initial:Record<string,any>;fields:Field[];context?:string}|null>(null)
const mode=computed(()=>String(route.meta.qualityView||'record')),manager=computed(()=>auth.canManage)
const occ=computed(()=>mode.value==='record'?data.value?.occurrences.find((o:any)=>o.id===route.params.id):null),audit=computed(()=>mode.value==='audit'?data.value?.audits.find((o:any)=>o.id===route.params.id):null)
const actions=computed(()=>data.value?.actions.filter((a:any)=>a.occurrence_id===occ.value?.id)||[]),proof=computed(()=>data.value?.attachments.filter((a:any)=>occ.value?a.occurrence_id===occ.value.id:mode.value==='actions'?a.action_id===uploadAction.value:a.audit_id===audit.value?.id)||[])
const checks=computed(()=>data.value?.completeness[occ.value?.id]),people=computed(()=>data.value?.profiles.filter((p:any)=>p.assignable).map((p:any)=>({value:p.id,label:p.full_name||p.id}))||[])
const typeOptions=[{value:'CORRECTION',label:'Correção'},{value:'CORRECTIVE',label:'Ação Corretiva'},{value:'IMPROVEMENT',label:'Melhoria'},{value:'RISK',label:'Risco/Oportunidade'},{value:'OPPORTUNITY',label:'Oportunidade de Melhoria'}]
const stateLabels:Record<string,string>={OPEN:'Aberta',IN_PROGRESS:'Em curso',AWAITING_EFFECTIVENESS:'A aguardar eficácia',CLOSED:'Encerrada',TODO:'Por iniciar',COMPLETED:'Concluída',CANCELLED:'Anulada',PENDING:'Pendente',SENDING:'Em envio',SENT:'Enviada',FAILED:'Falha no envio',DRAFT:'Rascunho',SUBMITTED:'Submetido',APPROVED:'Aprovado',RETURNED:'Devolvido',REJECTED:'Rejeitado',EFFECTIVE:'Eficaz',NOT_EFFECTIVE:'Não eficaz'}
const name=(id:string)=>data.value?.profiles.find((p:any)=>p.id===id)?.full_name||'Qualidade'
const day=datePT
const scopeOf=(a:any,kind:string)=>data.value.scope.filter((s:any)=>s.audit_id===a.id&&s.kind===kind)
const scopeName=(s:any)=>s.kind==='area'?data.value.areas.find((a:any)=>a.id===s.area_id)?.name:s.kind==='standard'?data.value.catalogs.find((c:any)=>c.id===s.standard_id)?.name:s.site
const context=(a:any)=>[a.reference+' · '+a.title,...data.value.scope.filter((s:any)=>s.audit_id===a.id).map(scopeName),a.auditor_entity].filter(Boolean).join(' · ')
const title=computed(()=>({audits:'Auditorias',audit:audit.value?.title||'Auditoria',record:occ.value?.reference||'Ocorrência',work:'O meu trabalho',search:'Pesquisa global',dashboard:'Visão Geral',notifications:'Notificações',settings:'Configuração operacional',actions:'Ações',new:'Nova ocorrência'}[mode.value]||'Qualidade'))
async function load(){busy.value=true;error.value='';try{data.value=await qualityWorkspace()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const {orgId}=useOrganization();watch(orgId,load)
onMounted(load);watch(()=>route.fullPath,()=>{search.value=String(route.query.q||'');filter.value=String(route.query.filter||'');void load()})
async function saved(result:any){dialog.value=null;await load();if(mode.value==='audits'&&result?.kind)await router.push('/auditorias/'+result.id);if(mode.value==='new'&&result?.id)await router.push('/ocorrencias/'+result.id)}
function open(title:string,operation:string,initial:Record<string,any>,fields:Field[],id?:string){dialog.value={title,operation,initial,fields,id}}
const person=(key='responsible_user_id',label='Responsável'):Field=>({key,label,options:key==='approver_id'?data.value.profiles.filter((p:any)=>p.can_approve).map((p:any)=>({value:p.id,label:p.full_name})):people.value})
const field=(key:string,label:string,type='text',required=false,details=false):Field=>({key,label,type,required,details})
const version=(r:any)=>({expected_version:r.version})
function auditForm(a:any=null){open(a?'Editar auditoria':'Nova auditoria','audit_save',a?{...a,...version(a),start_date:a.start_date?.slice(0,10)||'',end_date:a.end_date?.slice(0,10)||'',area_ids:scopeOf(a,'area').map((s:any)=>s.area_id),standard_ids:scopeOf(a,'standard').map((s:any)=>s.standard_id),site_names:scopeOf(a,'site').map((s:any)=>s.site)}:{kind:'INTERNAL',year:new Date().getFullYear(),area_ids:[],standard_ids:[],site_names:[]},[
 {key:'kind',label:'Tipo de auditoria',required:true,options:[{value:'INTERNAL',label:'Interna'},{value:'EXTERNAL',label:'Externa'}]},field('title','Título','text',true),field('year','Ano','number',true),field('start_date','Início','date'),field('end_date','Fim','date'),{key:'auditor_id',label:'Auditor responsável',options:data.value.auditors.filter((r:any)=>r.active||r.id===a?.auditor_id).map((r:any)=>({value:r.id,label:r.name+(r.active?'':' (inativo)')}))},
 {key:'area_ids',label:'Áreas / processos abrangidos',type:'multiple',required:true,options:data.value.areas.filter((r:any)=>r.active||a&&scopeOf(a,'area').some((s:any)=>s.area_id===r.id)).map((r:any)=>({value:r.id,label:r.name+(r.active?'':' (inativa)')}))},
 {key:'standard_ids',label:'Normas / referenciais',type:'multiple',options:data.value.catalogs.filter((r:any)=>r.kind==='standard'&&(r.active||a&&scopeOf(a,'standard').some((s:any)=>s.standard_id===r.id))).map((r:any)=>({value:r.id,label:r.name+(r.active?'':' (inativo)')}))},field('site_names','Sites abrangidos separados por vírgulas','list'),field('scope','Âmbito','textarea'),{...field('auditor_entity','Entidade auditora','text',true),when:{key:'kind',value:'EXTERNAL'}},field('team','Equipa auditora','textarea',false,true),...['external_kind','accreditation','certificate','contract_reference','representative','headcount','recommendation'].map((key,i)=>({...field(key,['Tipo de auditoria externa','Acreditação','N.º do certificado','Contrato / referência','Representante Samsys','Efetivo','Resultado / recomendação'][i]!,key==='headcount'?'number':'text',false,true),when:{key:'kind',value:'EXTERNAL'}})),field('conclusions','Conclusões','textarea',false,true)],a?.id)}
function occurrenceForm(type='NC'){
 const a=audit.value,initial:any={finding_type:type==='OM'?'OM':'NC Menor',audit_id:a?.id||null,occurrence_date:new Date().toLocaleDateString('sv-SE')}
 const fields:Field[]=[{key:'finding_type',label:'Tipo',required:true,options:[...data.value.catalogs.filter((c:any)=>c.kind==='nc_classification'&&c.active).sort((x:any,y:any)=>x.name==='NC Maior'?-1:y.name==='NC Maior'?1:0).map((c:any)=>({value:c.name,label:c.name})),{value:'OM',label:'Oportunidade de Melhoria'}]},field('description',a?'Texto original do auditor':'O que aconteceu?','textarea',true),{...person(),required:true},field('occurrence_date',a?'Data da constatação':'Data da ocorrência','date',true)]
 if(a){
  const areas=scopeOf(a,'area').filter((s:any)=>data.value.areas.find((r:any)=>r.id===s.area_id)?.active)
  if(!areas.length){error.value='Esta auditoria não tem áreas/processos ativos associados. Edite a auditoria para definir o âmbito antes de registar a constatação.';return}
  for(const [kind,key,label,col] of [['area','area_id','Área / processo','area_id'],['standard','standard_scope_id','Referencial da auditoria','id'],['site','site_scope_id','Site da auditoria','id']]){
   const choices=kind==='area'?areas:scopeOf(a,kind!).filter((s:any)=>kind!=='standard'||data.value.catalogs.find((r:any)=>r.id===s.standard_id)?.active)
   if(choices.length===1)initial[key!]=choices[0][col!]
   if(choices.length>1)fields.push({key:key!,label:label!,required:true,options:choices.map((s:any)=>({value:s[col!],label:scopeName(s)}))})
  }
 }else fields.push({key:'area_id',label:'Área / processo',required:true,options:data.value.areas.filter((r:any)=>r.active).map((r:any)=>({value:r.id,label:r.name}))},{key:'origin_id',label:'Origem',required:true,options:data.value.origins.filter((r:any)=>r.active).map((r:any)=>({value:r.id,label:r.name}))},{key:'standard_id',label:'Norma / referencial',details:true,options:data.value.catalogs.filter((r:any)=>r.kind==='standard'&&r.active).map((r:any)=>({value:r.id,label:r.name}))},field('site','Site','text',false,true))
 fields.push(field('external_reference','Referência externa','text',false,true),field('clause','Cláusula / requisito','text',false,true),field('internal_context','Contexto interno','textarea',false,true))
 open(a?'Adicionar constatação NC/OM':'Nova ocorrência','occurrence_create',initial,fields)
 if(a&&dialog.value)dialog.value.context=context(a)
}
async function deleteConfig(kind:string,r:any){if(!confirm('Eliminar este valor se nunca foi utilizado?'))return;await command('config_delete',r,{kind,confirm_delete:true})}
function standardForm(c:any=null){open(c?'Editar referencial':'Adicionar referencial','catalog_save',c?{kind:'standard',name:c.name,active:c.active}:{kind:'standard',active:true},[field('name','Designação do referencial','text',true)],c?.id);if(dialog.value)dialog.value.context='Para uma nova versão normativa, use Adicionar referencial e preserve a versão anterior.'}
function otherFinding(){open('Outra constatação','finding_create',{audit_id:audit.value.id},[{key:'classification',label:'Classificação',required:true,options:(data.value.settings[0]?.finding_classifications||['Observação']).filter((s:string)=>!['NC Menor','NC Maior'].includes(s)).map((s:string)=>({value:s,label:s}))},field('original_text','Texto original do auditor','textarea',true),field('internal_context','Contexto interno','textarea')])}
function treatment(){const o=occ.value;open('Tratamento da ocorrência','occurrence_save',{...version(o),cause_analysis:o.cause_analysis||'',root_cause:o.root_cause||'',corrective_required:o.corrective_required,corrective_reason:o.corrective_reason||'',internal_context:o.internal_context||'',effectiveness_criterion:o.effectiveness_criterion||'',effectiveness_due:o.effectiveness_due||'',...(manager.value?{responsible_user_id:o.responsible_user_id||'',approval_required:o.approval_required,approver_id:o.approver_id||'',effectiveness_required:o.effectiveness_required,recurrent:o.recurrent}:{})},[
 field('internal_context','Contexto interno','textarea'),...(o.type==='NC'?[field('cause_analysis','Análise da causa','textarea'),field('root_cause','Causa identificada / causa raiz','textarea'),{key:'corrective_required',label:'É necessária ação corretiva?',options:[{value:true,label:'Sim'},{value:false,label:'Não'}]},{...field('corrective_reason','Justificação da dispensa','textarea',true),when:{key:'corrective_required',value:false}}]:[]),field('effectiveness_criterion','Critério de eficácia','textarea'),field('effectiveness_due','Data prevista da eficácia','date'),...(manager.value?[person(),field('effectiveness_required','Exige avaliação da eficácia','checkbox'),field('approval_required','Tratamento sujeito a aprovação','checkbox'),person('approver_id','Aprovador'),field('recurrent','NC recorrente','checkbox')]:[])],o.id)}
function actionForm(a:any=null){const initial=a?{...version(a),description:a.description,completion_criterion:a.completion_criterion||'',effectiveness_criterion:a.effectiveness_criterion||'',effectiveness_due:a.effectiveness_due||'',...(manager.value?{action_kind:a.action_kind||'',responsible_user_id:a.responsible_user_id||'',evidencias_obrigatorias:a.evidencias_obrigatorias}:{})}:{occurrence_id:occ.value?.id||null,evidencias_obrigatorias:true};open(a?'Editar ação':'Nova ação','action_save',initial,[field('description','O que deve ser feito?','textarea',true),...(manager.value?[{key:'action_kind',label:'Tipo de ação',required:true,options:typeOptions},person()]:[]),...(!a?[field('deadline','Prazo original','date',true)]:[]),...(a?[{key:'status',label:'Estado de execução',options:[{value:'TODO',label:'Por iniciar'},{value:'IN_PROGRESS',label:'Em curso'}]}]:[]),field('completion_criterion','Critério de conclusão','textarea'),field('effectiveness_criterion','Critério de eficácia','textarea',false,true),field('effectiveness_due','Data prevista da eficácia','date',false,true),...(manager.value?[field('evidencias_obrigatorias','Evidência obrigatória','checkbox')]:[])],a?.id)}
function reasonOperation(op:string,label:string,r:any){open(label,op,version(r),[field('reason','Motivo','textarea',true)],r.id)}
function deadline(a:any){open('Alterar prazo','deadline_request',version(a),[field('new_deadline','Novo prazo','date',true),field('reason','Motivo da alteração','textarea',true)],a.id)}
function evaluate(){open('Avaliar eficácia','effectiveness',{...version(occ.value),criterion:occ.value.effectiveness_criterion||'',evidence_ids:proof.value.map((e:any)=>e.id)},[{key:'result',label:'Resultado',required:true,options:[{value:'EFFECTIVE',label:'Eficaz'},{value:'NOT_EFFECTIVE',label:'Não eficaz'}]},field('criterion','Critério utilizado','textarea',true),field('conclusion','Conclusão e evidências consideradas','textarea',true),{key:'evidence_ids',label:'Evidências consideradas',type:'multiple',required:true,options:proof.value.map((e:any)=>({value:e.id,label:e.file_name+' · '+e.description}))}],occ.value.id)}
function approve(){open('Decidir sobre o tratamento','approval_decide',version(occ.value),[{key:'decision',label:'Decisão',required:true,options:[{value:'APPROVED',label:'Aprovar'},{value:'RETURNED',label:'Devolver para correção'},{value:'REJECTED',label:'Rejeitar'}]},field('comment','Comentário (obrigatório ao devolver/rejeitar)','textarea')],occ.value.id)}
function external(){open('Resposta à Entidade Auditora','external_response',{...version(occ.value),status:occ.value.external_status,evidence_ids:proof.value.map((e:any)=>e.id)},[{key:'status',label:'Estado externo',required:true,options:['Por responder','Em preparação','Submetida','Aceite','Pendente de evidência/verificação','Fechada externamente'].map(s=>({value:s,label:s}))},field('cause_sent','Causa enviada','textarea'),field('correction','Correção apresentada','textarea'),field('corrective_action','Ação corretiva apresentada','textarea'),{key:'evidence_ids',label:'Evidências enviadas',type:'multiple',options:proof.value.map((e:any)=>({value:e.id,label:e.file_name+' · '+e.description}))},field('implementation_due','Prazo de implementação','date'),field('sent_at','Data de envio','datetime-local'),field('auditor_original_text','Texto original recebido do auditor','textarea'),field('auditor_name','Auditor'),field('responded_at','Data da resposta','datetime-local'),field('acceptance','Aceitação / rejeição'),field('additional_requests','Pedidos adicionais','textarea',false,true),field('future_verification','Verificação externa futura','textarea',false,true)],occ.value.id)}
async function command(op:string,r:any,p:any={}){error.value='';busy.value=true;try{await qualityCommand(op,r.id,{...version(r),...p});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const uploadDescription=ref(''),uploadAction=ref(''),uploadReview=ref(''),uploadResponse=ref('')
async function upload(ev:Event){const file=(ev.target as HTMLInputElement).files?.[0];if(!file)return;error.value='';busy.value=true;try{if(!uploadDescription.value.trim())throw new Error('Escreve uma descrição da evidência.');if(file.size>10*1024*1024)throw new Error('Máximo: 10 MB.');const content=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]!);r.onerror=reject;r.readAsDataURL(file)});await qualityCommand('evidence_add',null,{occurrence_id:occ.value?.id||data.value.actions.find((a:any)=>a.id===uploadAction.value)?.occurrence_id||null,audit_id:mode.value==='audit'?audit.value?.id:null,action_id:uploadAction.value||null,review_id:uploadReview.value||null,external_response_id:uploadResponse.value||null,file_name:file.name,description:uploadDescription.value,content_base64:content});uploadDescription.value='';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false;(ev.target as HTMLInputElement).value=''}}
async function download(e:any){try{await downloadEvidence(e)}catch(e){error.value=(e as Error).message}}
const today=new Date().toISOString().slice(0,10),near=new Date(Date.now()+7*86400000).toISOString().slice(0,10)
const activeOccurrences=computed(()=>data.value?.occurrences.filter((o:any)=>!o.cancelled_at)||[])
const pendingActions=computed(()=>data.value?.actions.filter((a:any)=>!['COMPLETED','CANCELLED'].includes(a.status)&&!data.value.occurrences.find((o:any)=>o.id===a.occurrence_id)?.cancelled_at)||[])
const tasks=computed(()=>{if(!data.value)return [];const mine:any[]=[];for(const a of pendingActions.value)if(a.responsible_user_id===auth.profile?.id)mine.push({id:a.id,label:a.reference+' · '+a.description,step:a.acknowledged_at?'Concluir ação e juntar evidência':'Confirmar tomada de conhecimento',deadline:day(a.deadline),to:a.occurrence_id?'/ocorrencias/'+a.occurrence_id:'/qualidade/acoes'});for(const o of activeOccurrences.value){if(o.responsible_user_id===auth.profile?.id&&o.status!=='CLOSED'&&(!o.acknowledged_at||!data.value.completeness[o.id]?.cause)||o.approver_id===auth.profile?.id&&o.approval_status==='SUBMITTED'||manager.value&&o.status==='AWAITING_EFFECTIVENESS')mine.push({id:o.id,label:o.reference+' · '+o.description,step:o.approval_status==='SUBMITTED'?'Decidir aprovação':o.status==='AWAITING_EFFECTIVENESS'?'Avaliar eficácia':!o.acknowledged_at?'Confirmar tomada de conhecimento':'Completar análise da causa e tratamento',deadline:day(o.effectiveness_due),to:'/ocorrencias/'+o.id})}if(manager.value)for(const d of data.value.deadlines.filter((d:any)=>d.status==='PENDING')){const a=data.value.actions.find((a:any)=>a.id===d.action_id);if(a)mine.push({id:d.id,label:a.reference,step:'Decidir alteração de prazo',deadline:day(d.new_deadline),to:a.occurrence_id?'/ocorrencias/'+a.occurrence_id:'/qualidade/acoes'})}return mine})
const searchRows=computed(()=>{if(!data.value)return [];const rows=[...data.value.audits.map((a:any)=>({...a,category:'Auditoria',text:a.title,to:'/auditorias/'+a.id})),...(filter.value==='cancelled'?data.value.occurrences:activeOccurrences.value).map((o:any)=>({...o,category:o.type,text:o.description,to:'/ocorrencias/'+o.id})),...data.value.actions.filter((a:any)=>a.status!=='CANCELLED'&&!data.value.occurrences.find((o:any)=>o.id===a.occurrence_id)?.cancelled_at).map((a:any)=>({...data.value.occurrences.find((o:any)=>o.id===a.occurrence_id),...a,category:'Ação',text:a.description,to:a.occurrence_id?'/ocorrencias/'+a.occurrence_id:'/qualidade/acoes'}))];return rows.filter(r=>(!search.value||`${r.reference} ${r.text} ${r.internal_context||''} ${r.cause_analysis||''} ${r.root_cause||''} ${r.scope||''}`.toLowerCase().includes(search.value.toLowerCase()))&&(!year.value||String(r.year||r.created_at?.slice(0,4))===year.value)&&(!auditFilter.value||r.audit_id===auditFilter.value||r.id===auditFilter.value)&&(!area.value||r.area_id===area.value)&&(!responsible.value||r.responsible_user_id===responsible.value)&&(!origin.value||r.origin_id===origin.value)&&(!auditor.value||r.auditor_entity?.includes(auditor.value)||data.value.audits.find((a:any)=>a.id===r.audit_id)?.auditor_entity?.includes(auditor.value))&&(!filter.value||r.status===filter.value||r.category===filter.value||filter.value==='overdue'&&r.category==='Ação'&&r.deadline<today&&!['COMPLETED','CANCELLED'].includes(r.status)||filter.value==='near'&&r.category==='Ação'&&r.deadline>=today&&r.deadline<=near&&!['COMPLETED','CANCELLED'].includes(r.status)||filter.value==='recurrent'&&r.category==='NC'&&r.recurrent||filter.value==='cancelled'&&r.cancelled_at||filter.value==='openNC'&&r.category==='NC'&&r.status!=='CLOSED'))})
const kpis=computed(()=>[{label:'NC abertas',value:activeOccurrences.value.filter((o:any)=>o.type==='NC'&&o.status!=='CLOSED').length,filter:'openNC'},{label:'Ações em atraso',value:pendingActions.value.filter((a:any)=>a.deadline&&a.deadline<today).length,filter:'overdue'},{label:'Ações próximas do prazo',value:pendingActions.value.filter((a:any)=>a.deadline>=today&&a.deadline<=near).length,filter:'near'},{label:'A aguardar eficácia',value:activeOccurrences.value.filter((o:any)=>o.status==='AWAITING_EFFECTIVENESS').length,filter:'AWAITING_EFFECTIVENESS'},{label:'NC recorrentes',value:activeOccurrences.value.filter((o:any)=>o.type==='NC'&&o.recurrent).length,filter:'recurrent'},{label:'Pendências minhas',value:tasks.value.length,filter:'mine'}])

</script>
<template>
 <div><PageHeader><template #title>{{title}}</template><template #breadcrumb>{{mode==='record'?'Qualidade › NC / OM':mode==='audit'?'Qualidade › Auditorias':'Qualidade'}}</template></PageHeader>
 <div v-if="error" class="alert alert-danger" role="alert">{{error}}</div><p v-if="busy&&!data">A carregar…</p>
 <template v-if="data">
 <div class="d-flex gap-2 mb-3 flex-wrap"><button v-if="mode!=='settings'" class="btn btn-outline-secondary" :disabled="busy" @click="load">Recarregar dados</button><button v-if="manager" class="btn btn-outline-secondary" @click="exportQuality(data)">Exportar dados</button><RouterLink to="/meu-trabalho" class="btn btn-outline-primary">O meu trabalho</RouterLink><RouterLink v-if="manager&&mode!=='settings'" to="/qualidade/configuracao" class="btn btn-outline-secondary">Configuração</RouterLink></div>
 <template v-if="mode==='dashboard'"><div class="row g-3"><div v-for="k in kpis" :key="k.label" class="col-md-4"><RouterLink :to="k.filter==='mine'?'/meu-trabalho':'/pesquisa?filter='+k.filter" class="sq-card d-block text-decoration-none"><span class="sq-muted">{{k.label}}</span><strong class="d-block fs-2">{{k.value}}</strong></RouterLink></div></div><div v-if="manager" class="sq-card mt-3"><h2 class="fs-5">Atenção da Qualidade</h2><p>Sem responsável: {{activeOccurrences.filter((o:any)=>!o.responsible_user_id&&o.status!=='CLOSED').length}} · Aprovações: {{activeOccurrences.filter((o:any)=>o.approval_status==='SUBMITTED').length}} · Respostas externas pendentes: {{activeOccurrences.filter((o:any)=>o.audit_id&&!['Aceite','Fechada externamente'].includes(o.external_status)&&data.audits.find((a:any)=>a.id===o.audit_id)?.kind==='EXTERNAL').length}}</p><RouterLink to="/notificacoes">Consultar notificações e falhas de envio</RouterLink></div></template>
 <div v-if="mode==='work'" class="sq-card"><p v-if="!tasks.length">Não tens intervenções pendentes.</p><table v-else class="sq-table"><thead><tr><th>Registo</th><th>O que fazer</th><th>Prazo</th></tr></thead><tbody><tr v-for="t in tasks" :key="t.id"><td><RouterLink :to="t.to">{{t.label}}</RouterLink></td><td>{{t.step}}</td><td>{{t.deadline}}</td></tr></tbody></table></div>
 <div v-if="mode==='audits'" class="sq-card"><button v-if="manager" class="btn btn-primary mb-3" @click="auditForm()">Nova auditoria</button><table class="sq-table"><thead><tr><th>Referência</th><th>Título</th><th>Tipo</th><th>Datas</th></tr></thead><tbody><tr v-for="a in data.audits" :key="a.id"><td><RouterLink :to="'/auditorias/'+a.id">{{a.reference}}</RouterLink></td><td>{{a.title}}</td><td>{{a.kind==='EXTERNAL'?'Externa':'Interna'}}</td><td>{{day(a.start_date)}} — {{day(a.end_date)}}</td></tr></tbody></table></div>
 <template v-if="mode==='audit'&&audit"><section class="sq-card mb-3"><div class="d-flex gap-2 mb-3"><button v-if="manager" class="btn btn-outline-primary" @click="auditForm(audit)">Editar auditoria</button><button v-if="manager" class="btn btn-primary" @click="occurrenceForm()">Adicionar constatação NC/OM</button><button v-if="manager" class="btn btn-outline-primary" @click="otherFinding">Outra classificação</button></div><p>{{audit.kind==='EXTERNAL'?'Externa · '+audit.auditor_entity:'Interna'}} · {{scopeOf(audit,'standard').map(scopeName).join(', ')||audit.standard}} · {{day(audit.start_date)}} — {{day(audit.end_date)}}</p><p>{{audit.scope}}</p><p>{{context(audit)}}</p><details><summary>Mais detalhes e conclusões</summary><dl><template v-for="(label,key) in {lead_auditor:'Auditor responsável',team:'Equipa',areas:'Áreas',sites:'Sites',external_kind:'Tipo externo',accreditation:'Acreditação',certificate:'N.º do certificado',contract_reference:'Contrato',representative:'Representante',headcount:'Efetivo',conclusions:'Conclusões',recommendation:'Recomendação'}" :key="key"><dt>{{label}}</dt><dd>{{key==='lead_auditor'&&(audit.auditor_id||audit.lead_auditor_id)?(data.auditors.find((r:any)=>r.id===audit.auditor_id)?.name||name(audit.lead_auditor_id)):key==='areas'?scopeOf(audit,'area').map(scopeName).join(', ')||audit.areas||'—':key==='sites'?scopeOf(audit,'site').map(scopeName).join(', ')||audit.sites||'—':audit[key]||'—'}}</dd></template></dl></details></section><section class="sq-card mb-3"><h2 class="fs-5">Constatações e estado do tratamento</h2><p v-for="o in data.occurrences.filter((o:any)=>o.audit_id===audit.id)" :key="o.id"><RouterLink :to="'/ocorrencias/'+o.id">{{o.reference}}</RouterLink> · {{o.cancelled_at?'Anulada':stateLabels[o.status]}} — {{o.original_text}}</p><p v-for="f in data.findings.filter((f:any)=>f.audit_id===audit.id)" :key="f.id">{{f.classification}} — {{f.original_text}}</p></section></template>
 <template v-if="mode==='record'&&occ"><p v-if="occ.standard_scope_id||occ.site_scope_id||occ.standard_id">Referencial: {{data.catalogs.find((c:any)=>c.id===(occ.standard_id||data.scope.find((s:any)=>s.id===occ.standard_scope_id)?.standard_id))?.name||'—'}} · Site: {{data.scope.find((s:any)=>s.id===occ.site_scope_id)?.site||occ.site||'—'}}</p>
 <section class="sq-card mb-3"><div class="d-flex gap-2 flex-wrap mb-3"><span class="badge bg-primary">{{occ.cancelled_at?'Anulada':stateLabels[occ.status]}}</span><span>{{occ.type}} · Responsável: {{name(occ.responsible_user_id)}}</span><RouterLink v-if="occ.audit_id" :to="'/auditorias/'+occ.audit_id">Consultar auditoria de origem</RouterLink></div><p v-if="occ.classification">Classificação: {{occ.classification}}</p><p style="white-space:pre-wrap">{{occ.original_text||occ.description}}</p><p v-if="occ.original_text" class="sq-muted">Texto original do auditor preservado. O contexto interno fica no tratamento.</p><div class="alert alert-info"><strong>Próximo passo</strong><p class="mb-1">{{checks?.next}}</p><p v-if="checks?.next_action" class="mb-0">{{name(checks.next_action.responsible_user_id)}} deve concluir {{checks.next_action.reference}} até {{day(checks.next_action.deadline)}}.</p></div><div class="d-flex gap-3 flex-wrap"><span v-for="(label,key) in {cause:'Causa',actions:'Ações',evidence:'Evidências',effectiveness:'Eficácia'}" :key="key">{{checks?.[key]?'✓':'○'}} {{label}}</span></div><button v-if="occ.responsible_user_id===auth.profile?.id&&!occ.acknowledged_at" class="btn btn-primary mt-3" :disabled="busy" @click="command('ack_occurrence',occ)">Tomei conhecimento</button><p v-else-if="occ.acknowledged_at" class="sq-muted mt-3 mb-0">Conhecimento confirmado por {{name(occ.acknowledged_by)}} em {{occ.acknowledged_at}}.</p></section>
 <section class="sq-card mb-3"><h2 class="fs-5">Tratamento</h2><p>{{occ.internal_context}}</p><div class="row"><div class="col-md-6"><strong>Análise da causa</strong><p>{{occ.cause_analysis||'Por preencher'}}</p></div><div class="col-md-6"><strong>Causa raiz</strong><p>{{occ.root_cause||'Por confirmar'}}</p></div></div><p>Ação corretiva: {{occ.corrective_required===null?'Por decidir':occ.corrective_required?'Necessária':'Dispensada — '+occ.corrective_reason}}</p><div class="d-flex gap-2 flex-wrap"><button v-if="!occ.cancelled_at&&occ.status!=='CLOSED'&&(manager||occ.responsible_user_id===auth.profile?.id)" class="btn btn-primary" @click="treatment">Editar tratamento</button><button v-if="occ.approval_required&&occ.approval_status!=='SUBMITTED'&&!occ.cancelled_at&&occ.status!=='CLOSED'&&(manager||occ.responsible_user_id===auth.profile?.id)" class="btn btn-outline-primary" @click="command('approval_submit',occ)">Submeter para aprovação</button><button v-if="occ.approval_status==='SUBMITTED'&&occ.approver_id===auth.profile?.id" class="btn btn-primary" @click="approve">Aprovar / devolver / rejeitar</button></div><p v-if="occ.approval_required" class="mt-2">Aprovação: {{stateLabels[occ.approval_status]}} · {{name(occ.approver_id)}}</p><details class="mt-3"><summary>Tratamento anterior (planos preservados)</summary><div v-for="p in data.legacy_plans.filter((p:any)=>p.occurrence_id===occ.id)" :key="p.id"><strong>{{p.codigo}} · {{p.titulo}}</strong><p>{{p.descricao}}</p><p>{{p.status}} · {{p.aprovado_em}}</p></div></details><details><summary>Histórico de aprovações</summary><p v-for="a in data.approvals.filter((a:any)=>a.occurrence_id===occ.id)" :key="a.id">{{a.created_at}} · {{name(a.actor_id)}} · {{stateLabels[a.decision]}} · {{a.comment}}</p></details></section>
 </template>
 <section v-if="(mode==='record'&&occ)||mode==='actions'" class="sq-card mb-3"><div class="d-flex justify-content-between"><h2 class="fs-5">Ações</h2><button v-if="manager&&!occ?.cancelled_at&&occ?.status!=='CLOSED'" class="btn btn-primary" @click="actionForm()">Nova ação</button></div><div v-for="a in mode==='actions'?data.actions:actions" :key="a.id" class="border-bottom py-3"><strong>{{a.reference}} · {{typeOptions.find(t=>t.value===a.action_kind)?.label||'Tipo por classificar'}}</strong><p>{{a.description}}</p><p class="sq-muted">{{name(a.responsible_user_id)}} · {{stateLabels[a.status]||a.status}} · Prazo atual: {{day(a.deadline)}} · Original: {{day(a.original_deadline)}}</p><p v-if="!['COMPLETED','CANCELLED'].includes(a.status)&&a.deadline&&a.deadline<today" class="text-danger">Em atraso</p><p v-if="a.completion_criterion">Conclusão: {{a.completion_criterion}}</p><div v-if="a.status!=='CANCELLED'&&(manager||a.responsible_user_id===auth.profile?.id)" class="d-flex gap-2 flex-wrap"><button class="btn btn-sm btn-outline-primary" @click="actionForm(a)">Editar ação</button><button v-if="a.responsible_user_id===auth.profile?.id&&!a.acknowledged_at" class="btn btn-sm btn-outline-primary" @click="command('ack_action',a)">Tomei conhecimento</button><button v-if="!['COMPLETED','CANCELLED'].includes(a.status)" class="btn btn-sm btn-outline-primary" @click="deadline(a)">Alterar prazo</button><button v-if="!['COMPLETED','CANCELLED'].includes(a.status)" class="btn btn-sm btn-primary" :disabled="busy" @click="command('action_complete',a)">Concluir ação</button><button v-if="manager&&a.status!=='CANCELLED'" class="btn btn-sm btn-outline-danger" @click="reasonOperation('action_cancel','Anular ação',a)">Anular ação</button></div><button v-if="manager||a.responsible_user_id===auth.profile?.id" class="btn btn-sm btn-outline-primary mt-2" @click="open('Comentar ação','comment',{occurrence_id:a.occurrence_id||null,action_id:a.id},[field('comment','Comentário','textarea',true)])">Comentar ação</button><p v-for="c in data.comments.filter((c:any)=>c.action_id===a.id)" :key="c.id" class="mt-2 mb-1">{{name(c.created_by)}} · {{day(c.created_at)}} — {{c.comment}}</p><details class="mt-2"><summary>Histórico de prazos</summary><div v-for="d in data.deadlines.filter((d:any)=>d.action_id===a.id)" :key="d.id">{{day(d.old_deadline)}} → {{day(d.new_deadline)}} · {{d.reason}} · {{stateLabels[d.status]||d.status}}<button v-if="manager&&d.status==='PENDING'" class="btn btn-sm btn-outline-primary ms-2" @click="command('deadline_decide',a,{change_id:d.id,decision:'APPROVED'})">Aprovar novo prazo</button><button v-if="manager&&d.status==='PENDING'" class="btn btn-sm btn-outline-danger ms-2" @click="open('Rejeitar alteração de prazo','deadline_decide',{...version(a),change_id:d.id,decision:'REJECTED'},[field('reason','Motivo','textarea',true)],a.id)">Rejeitar pedido</button></div></details></div></section>
 <section v-if="mode==='audit'&&audit||mode==='record'&&occ||mode==='actions'" class="sq-card mb-3"><h2 class="fs-5">Evidências e documentos</h2><div v-for="e in proof" :key="e.id" class="d-flex gap-2 mb-2"><button class="btn btn-link p-0" @click="download(e)">{{e.file_name}}</button><span>{{e.description}} · {{name(e.uploaded_by)}} · {{day(e.created_at)}}</span></div><details v-if="manager||occ?.responsible_user_id===auth.profile?.id||(mode==='actions'?data.actions:actions).some((a:any)=>a.responsible_user_id===auth.profile?.id)"><summary>Adicionar evidência</summary><label class="form-label mt-2" for="evidence-description">Descrição da evidência</label><input id="evidence-description" v-model="uploadDescription" class="form-control mb-2"/><label v-if="occ||mode==='actions'" for="evidence-action" class="form-label">Associar à ação (opcional)</label><select v-if="occ||mode==='actions'" id="evidence-action" v-model="uploadAction" class="form-select mb-2"><option value="">Evidência da ocorrência</option><option v-for="a in mode==='actions'?data.actions:actions" :key="a.id" :value="a.id">{{a.reference}} · {{a.description}}</option></select><div v-if="occ" class="row g-2 mb-2"><div class="col"><label for="evidence-review">Avaliação de eficácia (opcional)</label><select id="evidence-review" v-model="uploadReview" class="form-select"><option value="">Nenhuma</option><option v-for="r in data.reviews.filter((r:any)=>r.occurrence_id===occ.id)" :key="r.id" :value="r.id">Ciclo {{r.cycle}} · {{stateLabels[r.result]}}</option></select></div><div class="col"><label for="evidence-response">Resposta externa (opcional)</label><select id="evidence-response" v-model="uploadResponse" class="form-select"><option value="">Nenhuma</option><option v-for="r in data.external.filter((r:any)=>r.occurrence_id===occ.id)" :key="r.id" :value="r.id">{{day(r.created_at)}} · {{r.status}}</option></select></div></div><input type="file" aria-label="Ficheiro de evidência" class="form-control" :disabled="busy||!uploadDescription.trim()" accept=".pdf,.png,.jpg,.jpeg,.txt,.csv,.docx,.xlsx" @change="upload"/><small class="sq-muted">Até 10 MB. A evidência original é preservada.</small></details></section>
 <template v-if="mode==='record'&&occ"><p v-if="occ.audit_id" class="text-body-secondary">{{context(data.audits.find((a:any)=>a.id===occ.audit_id))}}</p><section class="sq-card mb-3"><h2 class="fs-5">Eficácia e encerramento</h2><p>{{occ.effectiveness_required?'Avaliação obrigatória':'Avaliação formal dispensada'}} · Data prevista: {{day(occ.effectiveness_due)}}</p><p>{{occ.effectiveness_criterion}}</p><ul v-if="checks?.missing.length"><li v-for="m in checks.missing" :key="m">{{m}}</li></ul><div v-if="manager" class="d-flex gap-2 flex-wrap"><button v-if="!occ.cancelled_at&&occ.status!=='CLOSED'" class="btn btn-primary" @click="evaluate">Avaliar eficácia</button><button v-if="!occ.cancelled_at&&occ.status!=='CLOSED'&&!occ.effectiveness_required" class="btn btn-outline-primary" @click="command('close',occ)">Encerrar</button><button v-if="!occ.cancelled_at&&occ.status==='CLOSED'" class="btn btn-outline-primary" @click="reasonOperation('reopen','Reabrir ocorrência',occ)">Reabrir</button><button v-if="!occ.cancelled_at" class="btn btn-outline-danger" @click="reasonOperation('cancel','Anular sem apagar histórico',occ)">Anular</button></div><div v-for="r in data.reviews.filter((r:any)=>r.occurrence_id===occ.id)" :key="r.id" class="mt-3 border-top pt-2"><strong>Ciclo {{r.cycle}} · {{stateLabels[r.result]}}</strong><p>{{r.criterion}} · {{r.conclusion}}</p><small>{{name(r.evaluator_id)}} · {{day(r.evaluated_at)}}</small></div></section>
 <section v-if="data.audits.find((a:any)=>a.id===occ.audit_id)?.kind==='EXTERNAL'" class="sq-card mb-3"><h2 class="fs-5">Resposta à Entidade Auditora</h2><p>Estado externo: {{occ.external_status}}. Independente da avaliação interna da eficácia.</p><button v-if="manager||occ.responsible_user_id===auth.profile?.id" class="btn btn-outline-primary" @click="external">Registar resposta / evolução</button><details v-for="r in data.external.filter((r:any)=>r.occurrence_id===occ.id)" :key="r.id" class="mt-3"><summary>{{day(r.created_at)}} · {{r.status}}</summary><p>Causa: {{r.cause_sent}}</p><p>Correção: {{r.correction}}</p><p>Ação corretiva: {{r.corrective_action}}</p><p style="white-space:pre-wrap">Texto original do auditor: {{r.auditor_original_text}}</p><p>{{r.additional_requests}} · {{r.future_verification}}</p></details></section>
 <section class="sq-card mb-3"><h2 class="fs-5">Comentários</h2><button v-if="manager||occ.responsible_user_id===auth.profile?.id||actions.some((a:any)=>a.responsible_user_id===auth.profile?.id)" class="btn btn-outline-primary mb-2" @click="open('Adicionar comentário','comment',{occurrence_id:occ.id},[field('comment','Comentário','textarea',true)])">Comentar</button><p v-for="c in data.comments.filter((c:any)=>c.occurrence_id===occ.id)" :key="c.id">{{name(c.created_by)}} · {{day(c.created_at)}} — {{c.comment}}</p></section><section class="sq-card"><h2 class="fs-5">Histórico imutável</h2><details v-for="h in data.history.filter((h:any)=>h.entity_id===occ.id||h.new_data?.occurrence_id===occ.id)" :key="h.id"><summary>{{day(h.created_at)}} · {{name(h.user_id)}} · {{h.action}}</summary><pre class="small" style="white-space:pre-wrap">{{JSON.stringify({antes:h.old_data,depois:h.new_data},null,2)}}</pre></details></section></template>
 <section v-if="mode==='search'" class="sq-card"><div class="row g-2 mb-3"><div class="col-md-6"><label for="quality-search" class="form-label">Referência ou texto</label><input id="quality-search" v-model="search" class="form-control"/></div><div class="col-md-3"><label for="quality-year" class="form-label">Ano</label><input id="quality-year" v-model="year" type="number" class="form-control"/></div><div class="col-md-3"><label for="quality-filter" class="form-label">Tipo / estado</label><select id="quality-filter" v-model="filter" class="form-select"><option value="">Todos</option><option v-for="v in ['Auditoria','NC','OM','Ação','OPEN','IN_PROGRESS','AWAITING_EFFECTIVENESS','CLOSED','overdue','near','recurrent','openNC','cancelled']" :key="v" :value="v">{{({overdue:'Ações em atraso',near:'Prazo próximo',recurrent:'Recorrentes',openNC:'NC abertas',cancelled:'Anuladas'} as Record<string,string>)[v]||stateLabels[v]||v}}</option></select></div></div><details class="mb-3"><summary>Mais filtros</summary><div class="row g-2"><div class="col"><label>Área</label><select v-model="area" class="form-select"><option value="">Todas</option><option v-for="a in data.areas" :key="a.id" :value="a.id">{{a.name}}</option></select></div><div class="col"><label>Responsável</label><select v-model="responsible" class="form-select"><option value="">Todos</option><option v-for="p in people" :key="p.value" :value="p.value">{{p.label}}</option></select></div><div class="col"><label>Origem</label><select v-model="origin" class="form-select"><option value="">Todas</option><option v-for="o in data.origins" :key="o.id" :value="o.id">{{o.name}}</option></select></div><div class="col"><label>Auditoria</label><select v-model="auditFilter" class="form-select"><option value="">Todas</option><option v-for="a in data.audits" :key="a.id" :value="a.id">{{a.reference}} · {{a.title}}</option></select></div><div class="col"><label>Entidade auditora</label><input v-model="auditor" class="form-control"/></div></div></details><table class="sq-table"><thead><tr><th>Referência</th><th>Tipo</th><th>Descrição</th><th>Estado</th></tr></thead><tbody><tr v-for="r in searchRows" :key="r.id"><td><RouterLink :to="r.to">{{r.reference}}</RouterLink></td><td>{{r.category}}</td><td>{{r.text}}</td><td>{{stateLabels[r.status]||r.status}}</td></tr></tbody></table></section>
 <section v-if="mode==='notifications'" class="sq-card"><h2 class="fs-5">As minhas notificações</h2><div v-for="n in data.notifications" :key="n.id" class="border-bottom py-2"><RouterLink :to="n.link||'/meu-trabalho'">{{n.title}}</RouterLink><p>{{n.message}}</p><button v-if="!n.read" class="btn btn-sm btn-outline-primary" @click="command('notification_read',n)">Marcar como lida</button></div><template v-if="manager"><h2 class="fs-5 mt-4">Fila de email</h2><p class="sq-muted">As operações ficam gravadas mesmo quando o email está indisponível.</p><table class="sq-table"><thead><tr><th>Assunto</th><th>Estado</th><th>Tentativas</th><th></th></tr></thead><tbody><tr v-for="n in data.outbox" :key="n.id"><td>{{n.subject}}<details v-if="n.last_error"><summary>Detalhes da falha</summary>{{n.last_error}}</details></td><td>{{stateLabels[n.status]||n.status}}</td><td>{{n.attempts}}</td><td><button v-if="n.status==='FAILED'" class="btn btn-sm btn-outline-primary" @click="command('notification_retry',n)">Reenviar</button></td></tr></tbody></table></template></section>
 <template v-if="mode==='settings'&&manager"><section class="sq-card mb-3"><h2 class="fs-5">Catálogos da Qualidade</h2><button class="btn btn-outline-primary me-2" @click="catalogManager='auditor'">Gerir Auditores</button><button class="btn btn-outline-primary" @click="catalogManager='area'">Gerir Áreas/Processos</button></section><QualityOperationalSettings :settings="data.settings[0]" :catalogs="data.catalogs" :people="data.profiles.filter((p:any)=>p.can_approve).map((p:any)=>({value:p.id,label:p.full_name}))" @saved="load"/><section class="sq-card mt-3"><h2 class="fs-5">Normas e referenciais</h2><div v-for="c in data.catalogs.filter((c:any)=>c.kind==='standard')" :key="c.id" class="d-flex flex-wrap align-items-center gap-2 mb-2"><span class="me-auto">{{c.name}} <small v-if="!c.active">(Inativo)</small></span><button class="btn btn-sm btn-outline-primary" @click="standardForm(c)">Editar</button><button class="btn btn-sm btn-outline-secondary" @click="command('catalog_save',c,{kind:'standard',name:c.name,active:!c.active})">{{c.active?'Desativar':'Ativar'}}</button><button class="btn btn-sm btn-outline-danger" @click="deleteConfig('catalog',c)">Eliminar</button></div><button class="btn btn-outline-primary" @click="standardForm()">Adicionar referencial</button></section></template>
 <section v-if="mode==='new'" class="sq-card"><button class="btn btn-primary" @click="occurrenceForm()">Registar NC / OM</button></section>
 </template><QualityCatalogManager v-if="catalogManager" :kind="catalogManager" @changed="data=$event" @close="catalogManager=null"/><QualityCommandForm v-if="dialog" v-bind="dialog" @close="dialog=null" @saved="saved"/>
 </div>
</template>
